 {page==='calendar'&&<><Head icon={CalendarDays} color="#ae91ff">Календарь</Head><section className="panel calendar-panel"><div className="calendar-month"><button type="button" aria-label="Предыдущий месяц" onClick={()=>setMonth(m=>new Date(m.getFullYear(),m.getMonth()-1,1))}><ChevronLeft size={20}/></button><strong>{month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</strong><button type="button" aria-label="Следующий месяц" onClick={()=>setMonth(m=>new Date(m.getFullYear(),m.getMonth()+1,1))}><ChevronRight size={20}/></button></div><div className="calendar-grid">{['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=><span className="calendar-weekday" key={d}>{d}</span>)}{Array.from({length:offset},(_,i)=><span key={'empty'+i}/>)}{Array.from({length:days},(_,i)=>{const date=localKey(new Date(month.getFullYear(),month.getMonth(),i+1));const count=dated.filter(e=>e.date===date).length+mealPlans.filter(p=>p.date===date).length;return <button type="button" key={date} className={'calendar-day '+(chosenDate===date?'selected ':'')+(date===today()?'current':'')} onClick={()=>setChosenDate(date)}><span>{i+1}</span>{count>0&&<i aria-label={count+' событий'}/>}</button>})}</div></section><section className="panel list-panel"><div className="panel-title"><h3>{dateFormat(chosenDate,{day:'numeric',month:'long',year:'numeric'})}</h3><button onClick={()=>add('general',chosenDate)}>Добавить <Plus size={14}/></button></div><div className="calendar-filters">{[['all','Все'],['payments','Платежи'],['birthdays','Дни рождения'],['health','Здоровье'],['meals','Питание'],['ideas','Идеи']].map(([id,label])=><button key={id} className={calendarFilter===id?'active':''} onClick={()=>setCalendarFilter(id)}>{label}</button>)}</div><List arr={filteredEvents.filter(i=>i.date===chosenDate)} empty={mealPlans.some(p=>p.date===chosenDate)?'':'На выбранную дату записей нет'} action="Добавить событие" click={()=>add('general',chosenDate)}/>{(calendarFilter==='all'||calendarFilter==='meals')&&mealPlans.filter(p=>p.date===chosenDate).map(p=><div className={"entry meal-calendar-entry "+(p.done?"is-done":"")} key={p.id}><span className="category-icon" style={{'--cat':'#f3b56b'}}><Utensils size={18}/></span><div className="entry-main"><strong>{p.name}</strong><small>Запланированное блюдо · {p.meal||'Питание'} · {p.servings||1} порц.</small></div><button className="check-button" title={p.done?"Отменить выполнение":"Отметить приготовленным"} onClick={()=>toggleMeal(p.id)}>{p.done?<Check size={18}/>:<span className="meal-check-empty"/>}</button></div>)}</section></>}
 {page==='finance'&&<><Head icon={Wallet} color="#b48cff">Финансы</Head><Tabs options={[["expense","Расходы"],["income","Доходы"],["debt","Долги"],["subscription","Подписки"]]} value={financeTab} onChange={setFinanceTab}/>{financeTab==='expense'?<><section className="panel finance-hero"><div className="muted">Расходы за месяц</div><div className="big-number">{rub(monthSum)}</div>{delta!==null&&<span className={'change-pill '+(delta>0?'up':'down')}>{delta>0?'+':''}{delta}% к прошлому месяцу</span>}<ChartLine data={daily}/><small className="chart-caption">Расходы по дням текущего месяца</small></section><section className="panel categories-panel"><div className="panel-title"><h3>Категории</h3><button onClick={()=>add('finance',today(),'expense')}>Добавить <Plus size={14}/></button></div>{categorySummary.length?categorySummary.map(([id,total])=>{const c=getCat({icon:id});const Icon=c[2];return <div className="category-row" key={id}><span className="category-icon" style={{'--cat':c[3]}}><Icon size={18}/></span><strong>{c[1]}</strong><b>{rub(total)}</b><small>{Math.round(total/Math.max(1,monthSum)*100)}%</small></div>}):<Empty text="Расходов за этот месяц пока нет" action="Добавить расход" click={()=>add('finance',today(),'expense')}/>}</section></>:<section className="panel finance-hero"><div className="muted">{financeTab==='income'?'Доходы':financeTab==='debt'?'Долги':'Подписки'}</div><div className="big-number">{rub(items.filter(i=>i.type==='finance'&&(i.kind===financeTab||(financeTab==='subscription'&&i.icon==='subscription'))).reduce((s,i)=>s+Number(i.amount||0),0))}</div><p className="muted">Записи этой категории</p></section>}<section className="panel list-panel"><div className="panel-title"><h3>История операций</h3><button onClick={()=>add('finance',today(),financeTab)}>Добавить <Plus size={14}/></button></div><List arr={items.filter(i=>i.type==='finance'&&(financeTab==='expense'?(i.kind==='expense'||!i.kind):i.kind===financeTab||(financeTab==='subscription'&&i.icon==='subscription')))} empty="Операций пока нет" action="Добавить" click={()=>add('finance',today(),financeTab)}/></section></>}
