 {page==='contact'&&<><div className="screen-head"><button className="back-link" onClick={()=>nav('profile')}><ChevronLeft size={17}/> Назад</button><h2>Сотрудничество и реклама</h2></div><section className="panel lumi50-panel"><h3>Предложить сотрудничество</h3><p>Расскажите о рекламе, партнёрстве или вашей идее. Ответим в Telegram.</p><label>Как к вам обращаться?</label><input maxLength={100} value={contactName} onChange={e=>setContactName(e.target.value)} placeholder="Имя или название компании"/><label>Ваше предложение</label><textarea rows={5} maxLength={3000} value={contactText} onChange={e=>setContactText(e.target.value)} placeholder="Что вы хотите предложить?"/><button className="kitchen-primary" disabled={auth.status!=='verified'||contactStatus==='Отправляем…'} onClick={submitContact}>Отправить предложение</button>{contactStatus&&<p role="status">{contactStatus}</p>}</section></>}
 {page==='admin'&&isOwner&&<><div className="screen-head"><button className="back-link" onClick={()=>nav('profile')}><ChevronLeft size={17}/> Назад</button><h2>Управление LUMI</h2></div><section className="panel lumi50-panel"><h3>Обзор <button onClick={refreshAdmin} disabled={adminBusy}>Обновить</button></h3>{adminData?.error?<p role="alert">{adminData.error}</p>:<><div className="lumi50-metrics"><div><small>Пользователей с данными</small><strong>{adminData?.users??'—'}</strong></div><div><small>Обращений</small><strong>{adminData?.contacts?.length??'—'}</strong></div></div><p className="kitchen-muted">Статистика считает Telegram ID с записями в Supabase, а не все открытия приложения.</p></>}</section><section className="panel lumi50-panel"><h3>Аналитика</h3><div className="lumi50-metrics"><div><small>Активных за 7 дней</small><strong>{insights?.active7??"—"}</strong></div><div><small>За 30 дней</small><strong>{insights?.active30??"—"}</strong></div><div><small>Показов рекламы</small><strong>{insights?.views??"—"}</strong></div><div><small>Кликов</small><strong>{insights?.clicks??"—"}</strong></div></div><h4>Популярные разделы</h4>{(insights?.sections||[]).map(v=><p key={v.section}>{v.section}: {v.count}</p>)}</section><section className="panel lumi50-panel"><h3>Обращения и чаты</h3>{adminData?.contacts?.length?adminData.contacts.map(c=><div className="lumi50-contact" key={c.id}><strong>{c.name||'Без имени'}</strong><small>Telegram ID: {c.telegram_id} · {new Date(c.created_at).toLocaleString('ru-RU')}</small><p>{c.message}</p><a href={'tg://user?id='+c.telegram_id}>Открыть Telegram</a>{c.last_reply_at&&<p className="kitchen-muted">Последний ответ: {new Date(c.last_reply_at).toLocaleString('ru-RU')} — {c.last_reply_text}</p>}<button className="kitchen-secondary" onClick={()=>loadChat(c)}>Загрузить историю переписки</button>{chatMessages[c.telegram_id]&&<div className="lumi51-chat">{chatMessages[c.telegram_id].map(m=><p key={m.id}><b>{m.direction==='in'?'Рекламодатель':'LUMI'}:</b> {m.text}<small> · {new Date(m.created_at).toLocaleString('ru-RU')}</small></p>)}</div>}<label>Ответить через @LumiPlannerBot</label><textarea rows={3} maxLength={2000} placeholder="Напишите ответ рекламодателю…" value={contactReplies[c.id]||''} onChange={e=>setContactReplies(prev=>({...prev,[c.id]:e.target.value}))}/><button className="kitchen-primary" disabled={replyBusy===c.id||adminBusy||!(contactReplies[c.id]||'').trim()} onClick={()=>sendContactReply(c)}>{replyBusy===c.id?'Отправляем…':'Отправить ответ в Telegram'}</button></div>):<p>Новых обращений пока нет.</p>}</section><section className="panel lumi50-panel"><h3>Рекламные кампании</h3><button className="kitchen-secondary" onClick={newCampaign}>+ Новая кампания</button><div className="lumi51-campaign-list">{campaigns.map(c=><button key={c.id} className={campaignId===c.id?"lumi51-selected":""} onClick={()=>selectCampaign(c)}>{c.title||"Без названия"} · {c.active?"Активна":"Выключена"} · {c.views||0} показов · {c.clicks||0} кликов</button>)}</div><label>Фото баннера (JPG, PNG, WebP до 2 МБ)</label><input type="file" accept="image/jpeg,image/png,image/webp" disabled={bannerUploading||adminBusy} onChange={e=>{uploadBannerImage(e.target.files?.[0]);e.target.value=''}}/>{bannerUploading&&<p className="kitchen-muted">Загружаем фото…</p>}{bannerImage&&<div className="lumi50-image-preview"><img src={bannerImage} alt="Предпросмотр баннера"/><button type="button" className="kitchen-secondary" onClick={()=>setBannerImage('')}>Убрать фото из баннера</button></div>}<label>Заголовок</label><input value={bannerTitle} maxLength={100} onChange={e=>setBannerTitle(e.target.value)} placeholder="Название партнёра"/><label>Ссылка (https://)</label><input value={bannerUrl} onChange={e=>setBannerUrl(e.target.value)} placeholder="https://example.com"/><label>Начало показа (необязательно)</label><input type="date" value={campaignStart} onChange={e=>setCampaignStart(e.target.value)}/><label>Показывать до (необязательно)</label><input type="date" value={bannerUntil} onChange={e=>setBannerUntil(e.target.value)}/><label className="lumi50-check"><input type="checkbox" checked={bannerActive} onChange={e=>setBannerActive(e.target.checked)}/> Показывать баннер</label><button className="kitchen-primary" onClick={saveBanner} disabled={adminBusy||bannerUploading}>Сохранить баннер</button><button className="kitchen-secondary lumi50-delete" onClick={deleteBanner} disabled={adminBusy||bannerUploading||!campaignId}>Удалить выбранную кампанию</button><p className="kitchen-muted">Можно включить несколько кампаний. Для остановки снимите галочку и сохраните.</p></section></>}
 {page==='profile'&&<><Head icon={UserRound}>Профиль</Head><section className="panel profile-card"><div className="profile-avatar">{(auth.user?.first_name||'L').slice(0,1).toUpperCase()}</div><strong>{auth.user?.first_name||'Пользователь LUMI'}</strong><small>{auth.status==='verified'?'Telegram подтверждён':auth.status==='checking'?'Проверка Telegram…':'Telegram не подтверждён'}</small></section><section className="panel list-panel"><div className="panel-title"><h3>Тема приложения</h3></div><Tabs options={[["dark","Тёмная"],["light","Светлая"],["auto","Системная"]]} value={theme} onChange={setTheme}/></section><div className="info-note"><Info size={17}/> Синхронизация Supabase: {syncStatus==='synced'?'данные синхронизированы':syncStatus==='syncing'?'синхронизация…':syncStatus==='waiting'?'ожидание авторизации':syncStatus.startsWith('error:')?'ошибка — '+syncStatus.slice(6):syncStatus}. Для синхронизации открой LUMI через Telegram на обоих устройствах. Уведомления бота пока не подключены.</div><button className="danger-button" onClick={()=>{if(window.confirm('Удалить все локальные записи LUMI?'))setItems([])}}><Trash2 size={17}/> Удалить локальные записи</button></>}
 {page==='profile'&&<section className="panel lumi50-panel"><h3>Мои достижения</h3><p>Уровень {gamification?.profile?.level||1} · {gamification?.profile?.xp||0} XP · серия {gamification?.profile?.streak||0} дн.</p><div className="lumi51-progress"><span style={{width:`${(gamification?.profile?.xp||0)%100}%`}}/></div><p className="kitchen-muted">За первое выполнение каждой задачи начисляется 10 XP. Достижения: {gamification?.profile?.xp>=100?"🏅 Первые 100 XP · ":""}{gamification?.profile?.xp>=500?"🏆 500 XP · ":""}{gamification?.profile?.streak>=3?"🔥 3 дня подряд":""}{!gamification?.profile?.xp?"Выполни первую задачу!":""}</p><label className="lumi50-check"><input type="checkbox" checked={rankingVisible} onChange={e=>changeRanking(e.target.checked)}/> Участвовать в общем рейтинге</label><h4>Рейтинг</h4>{leaderboard.map((u,i)=><p key={u.telegram_id}>{i+1}. {u.display_name||'Участник'} — {u.xp} XP</p>)}</section>}{page==='profile'&&<section className="panel lumi50-panel"><button className="kitchen-primary" onClick={()=>nav('contact')}>Сотрудничество и реклама</button>{isOwner&&<button className="kitchen-primary" onClick={()=>nav('admin')}>Админ-панель LUMI</button>}</section>}{page==='home'&&publicCampaigns.map(c=><button key={c.id} className="lumi50-banner lumi51-ad-button" onClick={()=>openAd(c)}><small>РЕКЛАМА</small>{c.image_url&&<img className="lumi50-banner-image" src={c.image_url} alt={c.title||'Рекламный баннер'} loading="lazy"/>}<strong>{c.title}</strong><span>Узнать подробнее →</span></button>)}
